diff --git a/libheif/color-conversion/alpha.cc b/libheif/color-conversion/alpha.cc
index 9055b70..d40d779 100644
--- a/libheif/color-conversion/alpha.cc
+++ b/libheif/color-conversion/alpha.cc
@@ -138,8 +138,12 @@ Op_flatten_alpha_plane<Pixel>::state_after_conversion(const ColorState& input_st
   // below, so every plane must be stored with sizeof(Pixel) bytes per sample. A file may
   // declare a different depth per plane ('unci'); reading a one-byte plane as two-byte
   // samples would run past its end (GHSA-r7gr-2xm2-23wf), and a plane wider than two
-  // bytes cannot be read through either instance. Decline anything else.
-  if (!input_state.all_channels_have_bytes_per_sample(static_cast<int>(sizeof(Pixel)))) {
+  // bytes cannot be read through either instance. For monochrome images, the colour
+  // width is sufficient here because the depth check below also covers alpha.
+  bool matching_storage = input_state.chroma == heif_chroma_monochrome
+                          ? input_state.color_channels_have_bytes_per_sample(static_cast<int>(sizeof(Pixel)))
+                          : input_state.all_channels_have_bytes_per_sample(static_cast<int>(sizeof(Pixel)));
+  if (!matching_storage) {
     return {};
   }

diff --git a/libheif/color-conversion/alpha.cc b/libheif/color-conversion/alpha.cc
index b585a7e..d8e4a48 100644
--- a/libheif/color-conversion/alpha.cc
+++ b/libheif/color-conversion/alpha.cc
@@ -143,10 +143,12 @@ Op_flatten_alpha_plane<Pixel>::state_after_conversion(const ColorState& input_st
     return {};
   }

-  // The colour planes are converted to RGB at one common depth and the alpha plane is
-  // composited at that depth, so all of them have to agree (0 = the colour planes differ).
+  // RGB compositing uses one common depth. The direct luma path weights alpha at its own
+  // depth, while the sample-width check above keeps both planes compatible with Pixel.
   int color_bpp = input_state.get_uniform_color_bits_per_pixel();
-  if (color_bpp == 0 || (input_state.has_alpha() && input_state.bits_per_pixel_alpha != color_bpp)) {
+  if (color_bpp == 0 ||
+      (input_state.has_alpha() && input_state.bits_per_pixel_alpha != color_bpp &&
+       input_state.chroma != heif_chroma_monochrome)) {
     return {};
   }

@@ -260,17 +262,16 @@ Op_flatten_alpha_plane<Pixel>::convert_colorspace(const std::shared_ptr<const He
                  "Op_flatten_alpha_plane: image has no alpha plane"};
   }

-  // The colour planes are converted at, and the alpha plane is composited at, one common depth
-  // through the 'Pixel' type of this instance.
+  // The colour planes must match Pixel; RGB compositing also uses that colour depth for alpha.
   int color_bpp = input_state.get_uniform_color_bits_per_pixel();
   int bpp_alpha = input_raw->get_bits_per_pixel(heif_channel_Alpha);

   if (color_bpp == 0 ||
-      bpp_alpha != color_bpp ||
+      (bpp_alpha != color_bpp && input_raw->get_chroma_format() != heif_chroma_monochrome) ||
       bytes_per_sample_for_bit_depth(color_bpp) != static_cast<int>(sizeof(Pixel))) {
     return Error{heif_error_Unsupported_feature,
                  heif_suberror_Unsupported_color_conversion,
-                 "Op_flatten_alpha_plane: colour and alpha planes must share one bit depth"};
+                 "Op_flatten_alpha_plane: incompatible colour or alpha depth"};
   }

   // See composite_plane(): the composite accumulates in 32 bits, which is exact for samples
